namespace ghidra.app.plugin.gui;






using docking;
using docking.widgets.list;
using generic.theme;
using generic.theme;
using ghidra.util;
using ghidra.util;

public class ThemeChooserDialog : DialogComponentProvider {

	private ThemeManager themeManager;
	private ListPanel<GTheme> listPanel;

	public ThemeChooserDialog(ThemeManager themeManager) : base("Change Theme")
    {
		this.themeManager = themeManager;

		addWorkPanel(buildMainPanel());
		addOKButton();
		addCancelButton();
		setRememberSize(false);
		setHelpLocation(new HelpLocation("Theming", "Switch_Theme"));
		updateButtonEnablement();
	}

	private void updateButtonEnablement() {

		GTheme selectedValue = listPanel.getSelectedValue();
		GTheme currentTheme = themeManager.getActiveTheme();
		bool canApplyTheme = selectedValue != null && !currentTheme.equals(selectedValue);
		setOkEnabled(canApplyTheme);
	}

	/* @Override */
	protected void okCallback() {
		applyTheme();
		close();
	}

	private void applyTheme() {
		GTheme selectedValue = listPanel.getSelectedValue();
		GTheme activeTheme = themeManager.getActiveTheme();
		if (selectedValue != null && selectedValue != activeTheme) {
			Swing.runLater(() => themeManager.setTheme(selectedValue));
		}
	}

	/* @Override */
	protected void cancelCallback() {
		close();
	}

	private JComponent buildMainPanel() {
		JPanel panel = new JPanel(new BorderLayout());
		panel.setBorder(BorderFactory.createEmptyBorder(10, 10, 0, 10));
		ThemeListModel model = new ThemeListModel();

		listPanel = new();
		listPanel.setListModel(model);
		listPanel.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		GTheme activeTheme = themeManager.getActiveTheme();
		listPanel.setSelectedValue(activeTheme);
		listPanel.addListSelectionListener(e => selectionChanged());
		listPanel.getAccessibleContext().setAccessibleName("Themes");
		panel.add(listPanel);
		listPanel.setDoubleClickActionListener(e => okCallback());
		panel.getAccessibleContext().setAccessibleName("Theme Chooser");
		return panel;
	}

	private void selectionChanged() {
		updateButtonEnablement();
	}

	private class ThemeListModel : AbstractListModel<GTheme> {
		private List<GTheme> allThemes;

		ThemeListModel() {
			allThemes = new(themeManager.getSupportedThemes());
			Collections.sort(allThemes, (t1, t2) => t1.getName().compareTo(t2.getName()));
		}

		/* @Override */
		public int getSize() {
			return allThemes.size();
		}

		/* @Override */
		public GTheme getElementAt(int index) {
			return allThemes.get(index);
		}

	}
}
